mod system;slint::include_modules!();
fn main() -> Result<(), slint::PlatformError> { let ui = MainWindow::new()?; let s=system::snapshot(); ui.set_os_name(s.os_name.into()); ui.set_cpu_name(s.cpu_name.into()); ui.set_cpu_count(s.cpu_count.into()); ui.set_ram_total(s.ram_total.into()); ui.set_ram_used(s.ram_used.into()); ui.set_ram_percent(s.ram_percent.into()); let weak=ui.as_weak(); ui.on_refresh_requested(move || { if let Some(ui)=weak.upgrade(){ let s=system::snapshot(); ui.set_os_name(s.os_name.into()); ui.set_cpu_name(s.cpu_name.into()); ui.set_cpu_count(s.cpu_count.into()); ui.set_ram_total(s.ram_total.into()); ui.set_ram_used(s.ram_used.into()); ui.set_ram_percent(s.ram_percent.into()); }}); ui.run() }
